"""S1 superior endplate: original image + predicted L5 polygon -> original-pixel endpoints."""
from pathlib import Path
import json,hashlib
import torch
CORE="from pathlib import Path\nimport json,hashlib\nimport numpy as np\nimport cv2\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom torchvision.models import resnet18\nfrom PIL import Image\nclass DecoderBlock(nn.Module):\n\n    def __init__(self, in_channels, skip_channels, out_channels):\n        super().__init__()\n        self.layers = nn.Sequential(nn.Conv2d(in_channels + skip_channels, out_channels, 3, padding=1, bias=False), nn.GroupNorm(8, out_channels), nn.ReLU(inplace=True), nn.Conv2d(out_channels, out_channels, 3, padding=1, bias=False), nn.GroupNorm(8, out_channels), nn.ReLU(inplace=True))\n\n    def forward(self, x, skip):\n        x = F.interpolate(x, size=skip.shape[-2:], mode='bilinear', align_corners=False)\n        return self.layers(torch.cat([x, skip], dim=1))\n\n\nclass EndplateNet(nn.Module):\n    def __init__(self,stride,use_global=False):\n        super().__init__()\n        assert stride in (2,4)\n        self.encoder=resnet18(weights=None)\n        self.encoder.fc=nn.Identity()\n        self.up3=DecoderBlock(512,256,256)\n        self.up2=DecoderBlock(256,128,128)\n        self.up1=DecoderBlock(128,64,64)\n        self.up0=DecoderBlock(64,64,32) if stride==2 else None\n        self.head=nn.Conv2d(32 if stride==2 else 64,2,1)\n        if use_global:\n            dim=512*int(np.prod(SETTINGS['feature_pool_hw']))\n            self.context_norm=nn.LayerNorm(dim)\n            self.context=nn.Sequential(nn.Linear(dim+8,256),nn.ReLU(),nn.Linear(256,1024))\n\n    def forward(self,x,context=None,position=None):\n        e=self.encoder\n        x0=e.relu(e.bn1(e.conv1(x)))\n        x1=e.layer1(e.maxpool(x0)); x2=e.layer2(x1)\n        x3=e.layer3(x2); x4=e.layer4(x3)\n        full=F.adaptive_avg_pool2d(x4,SETTINGS['feature_pool_hw']).flatten(1)\n        if hasattr(self,'context'):\n            assert context is not None and position is not None\n            gamma,beta=self.context(torch.cat([self.context_norm(context),position],1)).chunk(2,1)\n            x4=x4*(1+.1*gamma.tanh()[:,:,None,None])+beta[:,:,None,None]\n        out=self.up1(self.up2(self.up3(x4,x3),x2),x1)\n        if self.up0 is not None: out=self.up0(out,x0)\n        return self.head(out),full\n\n\ndef tensor_image(a):\n    rgb=np.repeat(np.asarray(a,dtype='float32')[None],3,axis=0)\n    rgb=(rgb-np.array([.485,.456,.406],dtype='float32')[:,None,None])/np.array([.229,.224,.225],dtype='float32')[:,None,None]\n    return torch.from_numpy(np.ascontiguousarray(rgb))[None].to(DEVICE)\n\n\ndef letterbox_geometry(width, height, output_hw):\n    oh, ow = map(int, output_hw)\n    scale = min(ow / width, oh / height)\n    nw, nh = (max(1, min(ow, round(width * scale))), max(1, min(oh, round(height * scale))))\n    left, top = ((ow - nw) // 2, (oh - nh) // 2)\n    sx, sy = (nw / width, nh / height)\n    matrix = np.array([[sx, 0, left + 0.5 * sx - 0.5], [0, sy, top + 0.5 * sy - 0.5], [0, 0, 1]], dtype=np.float64)\n    return (matrix, dict(new_hw=(nh, nw), pad_xy=(left, top)))\n\n\ndef make_letterbox(image, output_hw):\n    matrix, info = letterbox_geometry(image.shape[1], image.shape[0], output_hw)\n    oh, ow = output_hw\n    nh, nw = info['new_hw']\n    left, top = info['pad_xy']\n    output = np.zeros((oh, ow), dtype=np.float32)\n    output[top:top + nh, left:left + nw] = cv2.resize(image, (nw, nh), interpolation=cv2.INTER_LINEAR)\n    return (output, matrix)\n\n\nletterbox=make_letterbox\ndef xy(p, m):\n    p = np.asarray(p, float).reshape(-1,2)\n    return np.c_[p, np.ones(len(p))].dot(m.T)[:,:2]\n\n\ndef geom(p):\n    lo,hi=p.min(0),p.max(0); size=hi-lo\n    center=(lo+hi)/2 + [0,LC['down_factor']*size[1]]\n    side=LC['side_factor']*max(size)\n    assert side>1\n    left,top=center-side/2; sx,sy=W/side,H/side\n    return np.array([[sx,0,sx*(.5-left)-.5],[0,sy,sy*(.5-top)-.5],[0,0,1.]])\n\n\ndef input_data(c,p,training=False,image=None):\n    p=np.asarray(p,float).copy()\n    if training:\n        center=p.mean(0); size=np.ptp(p,axis=0)\n        p=(p-center)*np.random.uniform(1-LC['mask_scale'],1+LC['mask_scale'])+center\n        p+=np.random.uniform(-1,1,2)*size*LC['mask_shift']\n    m=geom(p)\n    if training:\n        rot=np.eye(3); rot[:2]=cv2.getRotationMatrix2D(((W-1)/2,(H-1)/2),np.random.uniform(-5,5),1)\n        if np.random.rand()<.5: rot=np.array([[-1,0,W-1],[0,1,0],[0,0,1.]])@rot\n        m=rot@m\n    a=cv2.warpAffine(gray(c) if image is None else image,m[:2],(W,H),flags=cv2.INTER_LINEAR)\n    mask=np.zeros((H,W),np.uint8)\n    cv2.fillPoly(mask,[np.rint(xy(p,m)).astype('int32')],1)\n    if training:\n        a=np.clip(a*np.random.uniform(.85,1.15)+np.random.uniform(-.06,.06),0,1)\n        k=np.ones((3,3),np.uint8)\n        if np.random.rand()<.5: mask=cv2.erode(mask,k)\n        else: mask=cv2.dilate(mask,k)\n    rgb=(np.repeat(a[None],3,axis=0)-np.array([.485,.456,.406])[:,None,None])/np.array([.229,.224,.225])[:,None,None]\n    x=torch.tensor(np.concatenate([rgb,mask[None]],0),dtype=torch.float32)\n    corners=xy([[0,0],[W-1,0],[0,H-1],[W-1,H-1]],np.linalg.inv(m))\n    pos=torch.tensor((2*(corners+.5)/[c['width'],c['height']]-1).ravel(),dtype=torch.float32)\n    return x,pos,m\n\n\ndef decode_l5(logits,c,mat):\n    maps=logits.float().sigmoid()[0].cpu().numpy()\n    assert np.isfinite(maps).all(), 'heatmap NaN/inf'\n    hm=np.array([[1/stride,0,.5/stride-.5],[0,1/stride,.5/stride-.5],[0,0,1.]])@mat\n    yy,xx=np.mgrid[:maps.shape[1],:maps.shape[2]]\n    original=xy(np.c_[xx.ravel(),yy.ravel()],np.linalg.inv(hm))\n    valid=((original>=-.5)&(original<=[c['width']-.5,c['height']-.5])).all(1).reshape(xx.shape)\n    assert valid.any(), 'L5 ROI가 원본 영상과 겹치지 않습니다.'\n    points=[]\n    for heat in maps:\n        y,x=np.unravel_index(np.where(valid,heat,-1).argmax(),heat.shape)\n        p=[float(x),float(y)]\n        for axis,(dx,dy) in enumerate(((1,0),(0,1))):\n            if not (0<=x-dx and x+dx<heat.shape[1] and 0<=y-dy and y+dy<heat.shape[0]): continue\n            if not (valid[y-dy,x-dx] and valid[y+dy,x+dx]): continue\n            a,b,d=np.log(np.maximum([heat[y-dy,x-dx],heat[y,x],heat[y+dy,x+dx]],1e-8))\n            curve=a-2*b+d\n            if curve< -1e-8: p[axis]+=float(np.clip(.5*(a-d)/curve,-.5,.5))\n        points.append(p)\n    return xy(points,np.linalg.inv(hm))\n\ndef canonical_pair(points):\n    p=np.asarray(points,float).reshape(2,2)\n    if not np.isfinite(p).all(): raise ValueError('끝점 NaN/inf')\n    return p[np.lexsort((p[:,1],p[:,0]))]\n\n\ndef l5_coordinates(points,polygon):\n    p=np.asarray(polygon,float).reshape(-1,2)\n    lo,hi=p.min(0),p.max(0); size=hi-lo\n    if not np.isfinite(p).all() or np.any(size<1): raise ValueError('L5 polygon 크기 오류')\n    # 네 좌표의 조합이 L5 대비 위치, 방향, 길이를 함께 표현.\n    anchor=np.array([(lo[0]+hi[0])/2,hi[1]])\n    return ((canonical_pair(points)-anchor)/size).reshape(4)\n\n\ndef prior_log_score(features,prior):\n    # 학습 정답의 다봉 분포를 허용하는 Student-t kernel mixture.\n    # 특정 위치/각도를 강제로 잘라내지 않고 점수로만 사용.\n    query=np.asarray(features,float).reshape(-1,4)\n    refs=np.asarray(prior['features']);scale=np.asarray(prior['scale'])*prior['bandwidth']\n    distance=(((query[:,None]-refs[None])/scale)**2).sum(2)\n    log_kernel=-(prior['df']+4)/2*np.log1p(distance/prior['df'])\n    terms=log_kernel+np.log(np.maximum(prior['weights'],1e-300))[None]\n    mx=terms.max(1)\n    log_density=mx+np.log(np.exp(terms-mx[:,None]).sum(1))\n    return np.maximum(log_density,-prior['penalty_cap'])\n\n\ndef heatmap_geometry(c,mat,shape):\n    mapping=np.array([[1/stride,0,.5/stride-.5],[0,1/stride,.5/stride-.5],[0,0,1.]])@mat\n    yy,xx=np.mgrid[:shape[0],:shape[1]]\n    original=xy(np.c_[xx.ravel(),yy.ravel()],np.linalg.inv(mapping))\n    valid=((original>=-.5)&(original<=[c['width']-.5,c['height']-.5])).all(1).reshape(shape)\n    if not valid.any(): raise ValueError('ROI가 원본 영상과 겹치지 않습니다.')\n    return mapping,valid\n\n\ndef spaced_candidates(heat,valid,mapping,polygon,settings):\n    scale=np.sqrt(abs(np.linalg.det(mapping[:2,:2])))\n    l5_size=float(np.ptp(np.asarray(polygon,float),axis=0).max())\n    radius=max(3,int(round(settings['nms_l5_fraction']*l5_size*scale)))\n    yy,xx=np.mgrid[:heat.shape[0],:heat.shape[1]]\n    scores=np.where(valid,heat,-np.inf).copy();points=[];values=[]\n    for _ in range(settings['candidates_per_endpoint']):\n        y,x=np.unravel_index(scores.argmax(),scores.shape)\n        if not np.isfinite(scores[y,x]): break\n        p=[float(x),float(y)]\n        for axis,(dx,dy) in enumerate(((1,0),(0,1))):\n            if not (0<=x-dx and x+dx<heat.shape[1] and 0<=y-dy and y+dy<heat.shape[0]): continue\n            if not(valid[y-dy,x-dx] and valid[y+dy,x+dx]): continue\n            a,b,d=np.log(np.maximum([heat[y-dy,x-dx],heat[y,x],heat[y+dy,x+dx]],1e-8))\n            curvature=a-2*b+d\n            if curvature< -1e-8:p[axis]+=float(np.clip(.5*(a-d)/curvature,-.5,.5))\n        points.append(p);values.append(float(heat[y,x]))\n        scores[(xx-x)**2+(yy-y)**2<=radius**2]=-np.inf\n    return xy(points,np.linalg.inv(mapping)),np.asarray(values),radius\n\n\ndef build_pair_bank(probabilities,baseline,c,mat,prior,settings):\n    # 추론용: S1 정답 c['points']를 참조하지 않음.\n    mapping,valid=heatmap_geometry(c,mat,probabilities.shape[-2:])\n    a,sa,ra=spaced_candidates(probabilities[0],valid,mapping,c['l5'],settings)\n    b,sb,rb=spaced_candidates(probabilities[1],valid,mapping,c['l5'],settings)\n    pairs=[np.asarray(baseline,float)]\n    heat_scores=[.5*(np.log(max(probabilities[0][valid].max(),1e-8))+np.log(max(probabilities[1][valid].max(),1e-8)))]\n    for i,pa in enumerate(a):\n        for j,pb in enumerate(b):\n            if pb[0]<pa[0] or np.linalg.norm(pb-pa)<1: continue\n            pair=np.stack([pa,pb])\n            if np.max(abs(pair-baseline))<1e-6:continue\n            pairs.append(pair);heat_scores.append(.5*(np.log(max(sa[i],1e-8))+np.log(max(sb[j],1e-8))))\n    features=np.array([l5_coordinates(p,c['l5']) for p in pairs])\n    return dict(pairs=np.asarray(pairs),heat=np.asarray(heat_scores),prior=prior_log_score(features,prior),\n                candidates=[a,b],nms_radius=ra)\n\n\ndef choose_pair(bank,strength):\n    # 강도 0이면 원래 decode 결과를 그대로 사용.\n    index=0 if strength==0 else int(np.argmax(bank['heat']+strength*bank['prior']))\n    return bank['pairs'][index].copy(),index\n\n\n@torch.no_grad()\ndef predict_s1_pair(gray01,l5_polygon):\n    # 새 영상 + 예측 L5 원본 윤곽만 사용. S1 GT 불필요.\n    a=np.asarray(gray01,dtype='float32');p=np.asarray(l5_polygon,float).reshape(-1,2)\n    assert a.ndim==2 and np.isfinite(a).all() and 0<=a.min()<=a.max()<=1\n    assert len(p)>=3 and np.isfinite(p).all() and abs(cv2.contourArea(p.astype('float32')))>1\n    assert (p>=0).all() and (p[:,0]<a.shape[1]).all() and (p[:,1]<a.shape[0]).all()\n    c=dict(width=a.shape[1],height=a.shape[0],l5=p.tolist())\n    full,_=letterbox(a,CFG['coarse_hw']);coarse_model.eval();model_l5.eval()\n    _,feature=coarse_model(tensor_image(full))\n    x,pos,mat=input_data(c,p,False,a)\n    logits,_=model_l5(x[None].to(DEVICE),feature,pos[None].to(DEVICE))\n    baseline=decode_l5(logits,c,mat)\n    b=build_pair_bank(logits.sigmoid()[0].cpu().numpy(),baseline,c,mat,PRIOR,PC)\n    pred,index=choose_pair(b,SELECTION['strength'])\n    return dict(points=pred.tolist(),original_points=baseline.tolist(),strength=SELECTION['strength'],selected_pair=index)\n\ndef read_gray(path):\n    # EXIF 회전을 자동 적용하면 라벨 좌표가 달라지므로 원본 배열 방향을 유지합니다.\n    with Image.open(path) as im:\n        if im.mode in {'RGB', 'RGBA', 'P', 'CMYK'}:\n            array = np.asarray(im.convert('L'), dtype=np.float32) / 255.0\n        else:\n            raw = np.asarray(im)\n            if raw.dtype == np.uint8:\n                array = raw.astype(np.float32) / 255.0\n            else:\n                array = raw.astype(np.float32)\n                low, high = np.percentile(array, [0.5, 99.5])\n                if not np.isfinite([low, high]).all() or high <= low:\n                    raise ValueError(str(path) + ': 영상 명암 범위가 유효하지 않습니다.')\n                array = np.clip((array - low) / (high - low), 0, 1)\n    if array.ndim != 2 or not np.isfinite(array).all():\n        raise ValueError(str(path) + ': 2차원 grayscale 영상이 필요합니다.')\n    return np.ascontiguousarray(array, dtype=np.float32)\n\n"

class S1Predictor:
    def __init__(self,bundle_dir,device=None):
        folder=Path(bundle_dir);meta=json.loads((folder/'bundle.json').read_text())
        for fn,sha in meta['sha256'].items():
            h=hashlib.sha256()
            with (folder/fn).open('rb') as f:
                for b in iter(lambda:f.read(2**20),b''):h.update(b)
            if h.hexdigest()!=sha:raise ValueError('bundle 파일 변경: '+fn)
        ns={};exec(CORE,ns)
        ns.update(CFG=meta['config'],SETTINGS=meta['context_settings'],LC=meta['l5_settings'],
            PC=meta['pair_settings'],PRIOR=json.loads((folder/'prior.json').read_text()),
            SELECTION=dict(strength=meta['strength']),DEVICE=torch.device(device or ('cuda' if torch.cuda.is_available() else 'cpu')))
        ns['H'],ns['W']=map(int,ns['CFG']['fine_hw']);ns['stride']=int(ns['CFG']['fine_stride'])
        weights=torch.load(folder/'weights.pt',map_location='cpu',weights_only=True)
        coarse=ns['EndplateNet'](ns['CFG']['coarse_stride']).to(ns['DEVICE']);coarse.load_state_dict(weights['coarse']);coarse.eval()
        model=ns['EndplateNet'](ns['CFG']['fine_stride'],True);old=model.encoder.conv1
        model.encoder.conv1=torch.nn.Conv2d(4,old.out_channels,old.kernel_size,old.stride,old.padding,bias=False)
        model.load_state_dict(weights['l5']);model.to(ns['DEVICE']).eval()
        ns.update(coarse_model=coarse,model_l5=model);self.ns=ns
    def predict(self,image,l5_polygon):
        a=self.ns['read_gray'](image) if isinstance(image,(str,Path)) else image
        return self.ns['predict_s1_pair'](a,l5_polygon)
